    relatedArticleIds: ['comm_dir_03_odra_kshatriya', 'comm_dir_12_vaddirajulu', 'comm_dir_14_gajapathulu', 'prof_cat_1_warriors', 'prof_cat_8_royal_heritage'],
    relatedKeywords: ['KalingaRajulu', 'Odra-Kshatriya', 'Gajapathulu', 'VaddiRajulu', 'Royal Heritage', 'Historical Warriors']
