    relatedArticleIds: ['comm_dir_01_od', 'comm_dir_10_vaddera', 'comm_dir_16_oddaru', 'prof_cat_3_construction_engineering', 'prof_cat_4_shilpi', 'prof_cat_6_lokashilpi'],
