    relatedArticleIds: ['comm_dir_03_odra_kshatriya', 'comm_dir_04_kalingarajulu', 'comm_dir_12_vaddirajulu', 'comm_dir_13_vadderarajulu', 'prof_cat_8_royal_heritage', 'prof_cat_1_warriors'],
